import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

// This component can be used both as a page and as a modal
const WalletModal = ({ onClose }) => {
  const { user } = useAuth();
  const [walletInfo, setWalletInfo] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  const [depositAmount, setDepositAmount] = useState('');
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [showDepositForm, setShowDepositForm] = useState(false);
  const [showWithdrawForm, setShowWithdrawForm] = useState(false);

  // Fetch wallet info and transactions
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [walletRes, transactionsRes] = await Promise.all([
          fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/balance/${user?.id}`, {
            headers: {
              'Authorization': `Bearer ${localStorage.getItem('token')}`
            }
          }),
          fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/transactions/${user?.id}`, {
            headers: {
              'Authorization': `Bearer ${localStorage.getItem('token')}`
            }
          })
        ]);

        const walletData = await walletRes.json();
        const transactionsData = await transactionsRes.json();

        setWalletInfo(walletData);
        setTransactions(transactionsData);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching wallet data:', error);
        setLoading(false);
      }
    };

    if (user) {
      fetchData();
    }
  }, [user]);

  const handleDeposit = async () => {
    if (!depositAmount || parseFloat(depositAmount) <= 0) {
      alert('Please enter a valid amount');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/deposit`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ 
          amount: parseFloat(depositAmount),
          method: 'credit_card' // Default method
        })
      });

      const data = await response.json();

      if (response.ok) {
        alert('Deposit successful!');
        setDepositAmount('');
        setShowDepositForm(false);
        // Refresh data
        window.location.reload();
      } else {
        alert(data.message || 'Deposit failed');
      }
    } catch (error) {
      console.error('Error processing deposit:', error);
      alert('Error processing deposit');
    }
  };

  const handleWithdraw = async () => {
    if (!withdrawAmount || parseFloat(withdrawAmount) <= 0) {
      alert('Please enter a valid amount');
      return;
    }

    if (parseFloat(withdrawAmount) > (walletInfo?.available || 0)) {
      alert('Insufficient balance');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/wallet/withdraw`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ 
          amount: parseFloat(withdrawAmount),
          method: 'bank_transfer' // Default method
        })
      });

      const data = await response.json();

      if (response.ok) {
        alert('Withdrawal successful!');
        setWithdrawAmount('');
        setShowWithdrawForm(false);
        // Refresh data
        window.location.reload();
      } else {
        alert(data.message || 'Withdrawal failed');
      }
    } catch (error) {
      console.error('Error processing withdrawal:', error);
      alert('Error processing withdrawal');
    }
  };

  if (loading) {
    return (
      <div className="wallet-loading">
        <div className="loading-container">
          <div className="loading-spinner"></div>
          <p>Loading wallet...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="wallet-content">
      <div className="wallet-header">
        <div className="balance-card">
          <h3>Total Balance</h3>
          <div className="balance-amount">
            {walletInfo?.total?.toLocaleString() || '0'} <span className="amp-symbol">AMP</span>
          </div>
          <div className="balance-available">
            Available: {walletInfo?.available?.toLocaleString() || '0'} AMP
          </div>
        </div>

        <div className="balance-card">
          <h3>Locked Funds</h3>
          <div className="balance-amount">
            {walletInfo?.locked?.toLocaleString() || '0'} <span className="amp-symbol">AMP</span>
          </div>
        </div>
      </div>

      <div className="wallet-actions">
        <div className="action-buttons">
          <button 
            className={`btn ${showDepositForm ? 'btn-secondary' : 'btn-primary'}`} 
            onClick={() => {
              setShowDepositForm(!showDepositForm);
              setShowWithdrawForm(false);
            }}
          >
            {showDepositForm ? 'Cancel' : 'Deposit'}
          </button>
          <button 
            className={`btn ${showWithdrawForm ? 'btn-secondary' : 'btn-primary'}`} 
            onClick={() => {
              setShowWithdrawForm(!showWithdrawForm);
              setShowDepositForm(false);
            }}
          >
            {showWithdrawForm ? 'Cancel' : 'Withdraw'}
          </button>
        </div>

        {(showDepositForm || showWithdrawForm) && (
          <div className="transaction-form">
            {showDepositForm && (
              <div className="form-group">
                <label className="form-label">Deposit Amount</label>
                <input
                  type="number"
                  className="form-control"
                  placeholder="Enter amount"
                  value={depositAmount}
                  onChange={(e) => setDepositAmount(e.target.value)}
                />
                <button className="btn btn-success" onClick={handleDeposit}>Confirm Deposit</button>
              </div>
            )}

            {showWithdrawForm && (
              <div className="form-group">
                <label className="form-label">Withdraw Amount</label>
                <input
                  type="number"
                  className="form-control"
                  placeholder="Enter amount"
                  value={withdrawAmount}
                  onChange={(e) => setWithdrawAmount(e.target.value)}
                />
                <button className="btn btn-danger" onClick={handleWithdraw}>Confirm Withdraw</button>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="wallet-transactions">
        <h3>Recent Transactions</h3>
        {transactions.length > 0 ? (
          <table className="table">
            <thead>
              <tr>
                <th>Type</th>
                <th>Amount</th>
                <th>Status</th>
                <th>Date</th>
              </tr>
            </thead>
            <tbody>
              {transactions.map((transaction) => (
                <tr key={transaction.id}>
                  <td>{transaction.type}</td>
                  <td>{transaction.amount} AMP</td>
                  <td>
                    <span className={`badge badge-${transaction.status === 'completed' ? 'success' : transaction.status === 'pending' ? 'warning' : 'danger'}`}>
                      {transaction.status}
                    </span>
                  </td>
                  <td>{new Date(transaction.timestamp).toLocaleDateString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>No transactions found.</p>
        )}
      </div>
    </div>
  );
};

// Main WalletPage component for routing
const WalletPage = () => {
  return <WalletModal />;
};

export default WalletPage;
export { WalletModal };
